void fftshift(std::vector<std::complex<float>>& x) {
    // element at index ceil(N/2) (first negative freq) moves to front
    std::rotate(x.begin(), x.begin() + (x.size() + 1) / 2, x.end());
}

void ifftshift(std::vector<std::complex<float>>& x) {
    std::rotate(x.begin(), x.begin() + x.size() / 2, x.end());
}
// N=5: [0,1,2,-2,-1] -> fftshift -> [-2,-1,0,1,2]
// N even: both rotate by N/2 and are identical

double peakFreq(const std::vector<float>& mag, size_t N, double fs) {
    if (mag.size() < 3) return 0.0;
    size_t k = 1;
    for (size_t i = 2; i + 1 < mag.size(); ++i)
        if (mag[i] > mag[k]) k = i;
    const double eps = 1e-30;
    double a = std::log(mag[k - 1] + eps);
    double b = std::log(mag[k] + eps);
    double c = std::log(mag[k + 1] + eps);
    double den = a - 2.0 * b + c;
    double p = (den != 0.0) ? 0.5 * (a - c) / den : 0.0;  // in [-0.5, 0.5]
    return (k + p) * fs / N;
}

